      const groups=new Map();rows.forEach(item=>{const k=key(item.color);if(!k)return;if(!groups.has(k))groups.set(k,[]);groups.get(k).push(item);});
      for(const [k,group] of groups){const newSource=group.find(x=>x.files?.length),existingSource=group.find(x=>x.existingImages?.length),source=newSource||existingSource;if(!source){colourAssets.set(k,{imageUrls:[],storagePaths:[]});continue;}if(newSource){const up=await uploadFiles(newSource.files.slice(0,1),'variants');colourAssets.set(k,{imageUrls:up.map(x=>x.url),storagePaths:up.map(x=>x.path)});}else colourAssets.set(k,{imageUrls:(source.existingImages||[]).slice(0,1),storagePaths:(source.existingPaths||[]).slice(0,1)});}
