    $('addVariantBtn')?.addEventListener('click',e=>{e.preventDefault();appendVariantRow({color:'',size:'',images:[],storagePaths:[]});});$('addColourSizesBtn')?.addEventListener('click',quickAddOptions);$('variantBulkSizes')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();quickAddOptions();}});$('variantBulkSizes')?.addEventListener('input',buildVariantBulkRateTable);$('variantBulkSeparatePrice')?.addEventListener('change',buildVariantBulkRateTable);$('variantBulkSeparateQty')?.addEventListener('change',()=>{if($('variantBulkSeparateQty').checked)$('trackInventory').checked=true;buildVariantBulkRateTable();updateInventoryControls();});$('variantBulkSharedImageBtn')?.addEventListener('click',()=>$('variantBulkSharedImage')?.click());$('variantBulkSharedImage')?.addEventListener('change',()=>{const file=$('variantBulkSharedImage')?.files?.[0];$('variantBulkSharedImageName').textContent=file?file.name:'No image selected';});$('variantSetupMode')?.addEventListener('change',handleVariantModeChange);$('optionTitle')?.addEventListener('input',updateVariantModeUI);$('barcodeEnabled')?.addEventListener('change',updateInventoryControls);$('trackInventory')?.addEventListener('change',updateInventoryControls);$('productStockQuantity')?.addEventListener('input',updateInventoryControls);
